(function(){register('Flow Field','Organic fluid lines drawn through a Perlin noise vector field.','generative',
function(c){c._first=1;c._n=new PerlinNoise();c._ps=Array.from({length:300},function(){return{x:Math.random(),y:Math.random(),h:Math.random()*360}})},
function(c,w,h,t){if(c._first){c.fillStyle='#0a0a0a';c.fillRect(0,0,w,h);c._first=0}c.fillStyle='rgba(0,0,0,.04)';c.fillRect(0,0,w,h);var n=c._n,ps=c._ps;for(var i=0;i<ps.length;i++){var p=ps[i];var ang=n.noise2d(p.x*3+t*.00012,p.y*3+t*.00012)*Math.PI*3+Math.PI*2*Math.sin(t*.00015+p.h*.01);var sp=2,nx=p.x+Math.cos(ang)*sp/w,ny=p.y+Math.sin(ang)*sp/h;c.beginPath();c.moveTo(p.x*w,p.y*h);c.lineTo(nx*w,ny*h);c.strokeStyle='hsla('+((p.h+t*.03)%360)+',75%,65%,.6)';c.lineWidth=1.5;c.stroke();p.x=nx;p.y=ny;if(p.x<0||p.x>1||p.y<0||p.y>1||Math.random()<.003){p.x=Math.random();p.y=Math.random();p.h=Math.random()*360}}}
,'Particles move through a Perlin noise vector field, tracing smooth paths that form organic flowing patterns.');})();

